styleCss:
@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:ital,wght@0,100;0,200;0,300;0,400;0,500;0,600;0,700;0,800;0,900;1,100;1,200;1,300;1,400;1,500;1,600;1,700;1,800;1,900&family=Inter:ital,opsz,wght@0,14..32,100..900;1,14..32,100..900&display=swap');

body.kp-default {
    background-color: #ffffff;
}
.research-header-menu-wrapper {
    background-color: #fff;
    height: 80px;
    border-bottom: solid 2px #185468;
}

.rp-header-logo img {
    width: 90px;
    height: 90px;
    position: absolute;
    left: 20px;
    top: 10px;
    background-color: #ffffff;
z-index: 2;
border: solid 4px #ffffff;
    border-radius: 45px;
}

.research-header-menu-wrapper ul {
    position: absolute;
    left: 140px;
    top: 50px;
}

.research-header-menu-wrapper ul li.menu a {
    color: #185468 !important;
    font-family: 'Barlow Condensed';
    font-style: normal;
    font-weight: 500;
    font-size: 20px;
    line-height: 24px;
}

.mdkp-body {
    background: #ffffff;
    padding: 0 !important;
    margin-bottom: 200px;
}

.paper-footer-wrapper {
display: none;
}

#kpn_portal_footer {
    position: absolute;
    width: 100%;
    height: 200px;
    background-color: #185468;
    color: #ffffff;
    z-index: 1;
    bottom: 0;
    left: 0;
}

#kpn_portal_footer .footer-logo{
display: block;
position: absolute;
width: 100px;
height: 125px;
right: 100px;
top: -20px;
}

#kpn_portal_footer .footer-logo img{
width: 95px;
    height: 95px;
    border: solid 1px #ffffff;
    border-radius: 50px;
}

#kpn_portal_footer .footer-logo span{
    display: block;
    position: absolute;
    bottom: 0;
    font-size: 9px;
    white-space: nowrap;
}

.card.mdkp-card {
    border: none;
}

.multi-section {
border: none !important;
}

.mdkp-card.dataset-page-header {
    display: none;
}

#rp_tabs_contents {
border: none;
}

.footer-menu-wrapper{
position:relative;
display: flex;
padding: 20px 80px;
gap: 50px;
}
.footer-contact {
    display: flex;
    flex-direction: column;
    width: 260px;
    align-items: flex-start;
    gap: 5px;
}
.footer-contact-title {
    font-size: 20px;
 font-family: 'Barlow Condensed';
}
.footer-contact-body {
    text-align: left;
    line-height: normal;
}
.footer-contact-social {
    display: flex;
    gap: 5px;
}
.footer-contact-social img {
    width: 20px;
    height: unset;
    position: relative;
    left: unset;
    top: unset;
    background: none;
    border: none;
    border-radius: 0;
}
ul.footer-menu {
    position: relative;
    height: fit-content;
    top: 0;
    left: 0;
    display: flex;
    font-size: 20px;
    flex-direction: column;
    flex-wrap: wrap;
    gap: 5px;
    max-height: 150px;
    align-items: baseline;
    column-gap: 40px;
font-family: 'Barlow Condensed';
}
.footer-menu a,
.footer-menu a:visited{
color:white !important;
text-decoration:none;
}
.footer-menu a:hover{
text-decoration:underline;
}
